using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

// The [McpServerToolType] attribute registers this class as a container for MCP tools.
// The MCP SDK scans for these at startup and wires them into the tool registry.
[McpServerToolType]
public sealed class WeatherTools
{
    // Each [McpServerTool] method becomes a callable tool exposed to the LLM.
    // [Description] provides the tool's purpose — the LLM reads this to decide when to call it.
    // Parameter-level [Description] attributes document each argument for the LLM.
    //
    // DI: The HttpClient parameter is constructor-injected by the DI container.
    //     Any registered service can appear as a parameter on the tool method —
    //     the MCP SDK resolves them from IServiceProvider automatically.

    [McpServerTool, Description("Get current weather for a city")]
    public static async Task<string> GetCurrentWeather(
        HttpClient httpClient,
        [Description("City name, e.g. 'London' or 'New York'")] string city,
        [Description("Units: 'metric' or 'imperial' (default: metric)")] string units = "metric",
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.weatherapi.com/v1/current.json?q={Uri.EscapeDataString(city)}&units={units}";

        try
        {
            var response = await httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);

            if (response is null)
                return $"No weather data found for '{city}'.";

            return $"""
                Weather for {response.Location?.Name}, {response.Location?.Country}:
                  Temperature: {response.Current?.TempC}°C / {response.Current?.TempF}°F
                  Condition:   {response.Current?.Condition?.Text}
                  Humidity:    {response.Current?.Humidity}%
                  Wind:        {response.Current?.WindKph} km/h
                """;
        }
        catch (HttpRequestException ex)
        {
            return $"Error fetching weather for '{city}': {ex.Message}";
        }
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city")]
    public static async Task<string> GetForecast(
        HttpClient httpClient,
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://api.weatherapi.com/v1/forecast.json?q={Uri.EscapeDataString(city)}&days={days}";

        try
        {
            var response = await httpClient.GetFromJsonAsync<ForecastResponse>(url, cancellationToken);

            if (response?.Forecast?.Days is not { Count: > 0 })
                return $"No forecast data found for '{city}'.";

            var lines = response.Forecast.Days.Select(d =>
                $"  {d.Date}: {d.Day?.Condition?.Text}, " +
                $"High {d.Day?.MaxTempC}°C / Low {d.Day?.MinTempC}°C");

            return $"Forecast for {city}:\n{string.Join('\n', lines)}";
        }
        catch (HttpRequestException ex)
        {
            return $"Error fetching forecast for '{city}': {ex.Message}";
        }
    }
}

// --- Response models ---

public sealed class WeatherResponse
{
    [JsonPropertyName("location")] public LocationInfo? Location { get; set; }
    [JsonPropertyName("current")]  public CurrentWeather? Current { get; set; }
}

public sealed class ForecastResponse
{
    [JsonPropertyName("location")] public LocationInfo? Location { get; set; }
    [JsonPropertyName("forecast")] public ForecastInfo? Forecast { get; set; }
}

public sealed class LocationInfo
{
    [JsonPropertyName("name")]    public string? Name { get; set; }
    [JsonPropertyName("country")] public string? Country { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temp_c")]    public double TempC { get; set; }
    [JsonPropertyName("temp_f")]    public double TempF { get; set; }
    [JsonPropertyName("humidity")]  public int Humidity { get; set; }
    [JsonPropertyName("wind_kph")]  public double WindKph { get; set; }
    [JsonPropertyName("condition")] public ConditionInfo? Condition { get; set; }
}

public sealed class ForecastInfo
{
    [JsonPropertyName("forecastday")] public List<ForecastDay> Days { get; set; } = [];
}

public sealed class ForecastDay
{
    [JsonPropertyName("date")] public string? Date { get; set; }
    [JsonPropertyName("day")]  public DayInfo? Day { get; set; }
}

public sealed class DayInfo
{
    [JsonPropertyName("maxtemp_c")] public double MaxTempC { get; set; }
    [JsonPropertyName("mintemp_c")] public double MinTempC { get; set; }
    [JsonPropertyName("condition")] public ConditionInfo? Condition { get; set; }
}

public sealed class ConditionInfo
{
    [JsonPropertyName("text")] public string? Text { get; set; }
}

